SELECT DISTINCT m.chembl_id, m.pref_name, cs.canonical_smiles, m.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id AS target_chembl_id, td.pref_name AS target_name FROM molecule_dictionary m INNER JOIN drug_mechanism dm ON dm.molregno = m.molregno INNER JOIN compound_structures cs ON cs.molregno = m.molregno LEFT JOIN target_dictionary td ON dm.tid = td.tid WHERE m.max_phase = 4 AND cs.canonical_smiles IS NOT NULL ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, m.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id, td.pref_name
